(()=>{'use strict';const bottom=document.querySelector('.desk-bottom'),identity=document.querySelector('#deskIdentity');if(!bottom||!identity)return;const trigger=document.createElement('button');trigger.type='button';trigger.className='account-more';trigger.textContent='⋮';trigger.setAttribute('aria-label','اطلاعات و تنظیمات حساب');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls','accountMorePanel');bottom.append(trigger);const panel=document.createElement('section');panel.id='accountMorePanel';panel.className='account-more-panel';panel.hidden=true;panel.setAttribute('aria-label','اطلاعات و تنظیمات حساب');const role=document.createElement('p');role.className='account-role-info';panel.append(role);document.body.append(panel);const settingsButton=document.createElement('button');settingsButton.type='button';settingsButton.className='account-settings-link';settingsButton.textContent='تنظیمات حساب کاربری';settingsButton.onclick=()=>{close();if(!document.body.classList.contains('shared-app'))return;selectedTask=null;const person=mine();if(!person)return;modal(modalHead('حساب کاربری')+'<section class="account-profile-details"><b>'+esc(person.name)+'</b><p>'+esc(person.title||'')+'</p><p dir="ltr">'+esc(session?.user.email||'')+'</p><button type="button" class="secondary" id="accountChangePassword">تغییر رمز شخصی</button><p class="shared-meta">تغییر رمز فقط برای حساب خودتان انجام می‌شود.</p></section>');document.querySelector('#accountChangePassword').onclick=()=>{document.querySelector('#sharedDialog').close();passwordSetup=true;passwordForm()}};panel.append(settingsButton);function sync(){settingsButton.hidden=!document.body.classList.contains('shared-app')||typeof mine!=='function'||!mine();for(const node of [...bottom.children])if(node!==identity&&node!==trigger)panel.append(node);const label=identity.querySelector('.role-label')||panel.querySelector('.role-label');if(label){if(label.parentElement!==panel)panel.append(label);let name=bottom.querySelector('.account-demo-name');if(!name){name=document.createElement('b');name.className='account-demo-name';identity.append(name)}const text=label.querySelector('select')?.selectedOptions[0]?.textContent?.split('·')[0].trim()||'';if(name.textContent!==text)name.textContent=text}panel.querySelectorAll('.mobile-account-actions button').forEach(b=>{const text=b.textContent.trim();b.dataset.accountAction=text.includes('خروج')?'signout':text.includes('رمز')?'password':text.includes('حذف')?'trash':'notifications'});const title=identity.querySelector('small')?.textContent||'';if(role.textContent!==title)role.textContent=title;role.hidden=!title;const push=panel.querySelector('.push-preferences');if(push&&!push.closest('.account-notification-settings')){const fold=document.createElement('details'),summary=document.createElement('summary');fold.className='account-notification-settings';summary.textContent='اعلان‌های این دستگاه';push.before(fold);fold.append(summary,push)}}function place(){const r=trigger.getBoundingClientRect();panel.style.visibility='hidden';panel.hidden=false;const p=panel.getBoundingClientRect(),scale=p.width/(panel.offsetWidth||p.width)||1;panel.style.left=Math.max(8,Math.min(innerWidth-p.width-8,r.right-p.width))/scale+'px';panel.style.top=Math.max(8,r.top-p.height-10)/scale+'px';panel.style.visibility='visible'}function close(focus=false){panel.hidden=true;trigger.setAttribute('aria-expanded','false');if(focus)trigger.focus()}trigger.onclick=()=>{if(!panel.hidden)return close();sync();place();trigger.setAttribute('aria-expanded','true')};document.addEventListener('pointerdown',e=>{if(!panel.hidden&&!panel.contains(e.target)&&!trigger.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){close(true);e.stopPropagation()}});panel.addEventListener('toggle',()=>{if(!panel.hidden)place()},true);window.addEventListener('resize',()=>close());new MutationObserver(sync).observe(bottom,{childList:true});new MutationObserver(sync).observe(identity,{childList:true,subtree:true,characterData:true});document.addEventListener('change',e=>{if(panel.contains(e.target))sync()});const previous=render;render=function(...a){const r=previous(...a);sync();return r};sync()})();
